        // Load tile from B into shared memory
        int b_row = t * BLOCK_SIZE + ty;
        for (int j = 0; j < REG_TILE_SIZE; j++) {
            if (b_row < K && col + j < N) {
                Bs[ty][tx * REG_TILE_SIZE + j] = B[b_row * N + col + j];
            } else {
                Bs[ty][tx * REG_TILE_SIZE + j] = 0.0f;
            }
