                    sum[i][j] += As[ty * REG_TILE_SIZE + i][k+1] * Bs[k+1][tx * REG_TILE_SIZE + j];
                    sum[i][j] += As[ty * REG_TILE_SIZE + i][k+2] * Bs[k+2][tx * REG_TILE_SIZE + j];
                    sum[i][j] += As[ty * REG_TILE_SIZE + i][k+3] * Bs[k+3][tx * REG_TILE_SIZE + j];
                }
            }
        }

        __syncthreads();
    }

